local OrbMaker = {}
local PRODUCTS = {
    wooden_orb = { name = "Lesena obla", woodCost = 1, time = 1, cost = 8, prestige = 1, description = "Preprosta lesena obla za sodnike." },
    brass_orb = { name = "Medeninasta obla", brassCost = 2, time = 2, cost = 30, prestige = 2, happiness = 1, description = "Medeninasta obla za uradnike." },
    silver_orb = { name = "Srebrna obla", silverCost = 2, time = 3, cost = 90, prestige = 5, happiness = 1, description = "Srebrna obla z vgraviranim križem." },
    gold_orb = { name = "Zlata obla", goldCost = 1, silverCost = 1, time = 4, cost = 220, prestige = 10, happiness = 2, description = "Zlata obla za kralje." },
    jewel_orb = { name = "Draguljna obla", goldCost = 2, jewelCost = 1, time = 6, cost = 480, prestige = 18, happiness = 4, description = "Z dragulji okrašena obla." },
    royal_imperial_orb = { name = "Kraljevska cesarska obla", goldCost = 3, silverCost = 2, jewelCost = 3, pearlCost = 1, time = 9, cost = 1100, prestige = 40, happiness = 8, description = "Cesarska obla z dragulji in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Oblarska delavnica", cost = { gold = 280, wood = 120 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Oblarska kovačija", cost = { gold = 850, wood = 220, stone = 180, gold = 8 }, upkeep = 20, qualityBonus = 18 },
    jewel_room = { name = "Draguljna soba", cost = { gold = 1900, wood = 300, stone = 400, silver = 40, jewel = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_orb_atelier = { name = "Kraljevski atelje obel", cost = { gold = 7000, wood = 600, stone = 800, gold = 80, jewel = 25 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 33 },
}
OrbMaker.woodStock = 14; OrbMaker.brassStock = 8; OrbMaker.silverStock = 8; OrbMaker.goldStock = 6; OrbMaker.jewelStock = 6; OrbMaker.pearlStock = 4
OrbMaker.productStock = {}; OrbMaker.buildings = {}; OrbMaker.maker = nil; OrbMaker.activeMaking = {}; OrbMaker.totalProducts = 0; OrbMaker.dayTimer = 0
function OrbMaker.init() OrbMaker.woodStock=14; OrbMaker.brassStock=8; OrbMaker.silverStock=8; OrbMaker.goldStock=6; OrbMaker.jewelStock=6; OrbMaker.pearlStock=4; OrbMaker.productStock={}; OrbMaker.buildings={}; OrbMaker.maker=nil; OrbMaker.activeMaking={}; OrbMaker.totalProducts=0; OrbMaker.dayTimer=0; print("[OrbMaker] Royal Orb Maker System initialized (6 products, 4 buildings)") end
function OrbMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OrbMaker.maker={name=n or ("Oblar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblar najet: %s (spretnost: %d)",OrbMaker.maker.name,s),"success") end; return true end
function OrbMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OrbMaker.build(id) local ok,e=OrbMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OrbMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OrbMaker.getQualityBonus() local b=0; for _,bd in ipairs(OrbMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OrbMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and OrbMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and OrbMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and OrbMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and OrbMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and OrbMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and OrbMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #OrbMaker.buildings==0 then return false,"Potrebna delavnica" end; if not OrbMaker.maker then return false,"Potreben oblar" end; return true end
function OrbMaker.make(pt,qty) qty=qty or 1; local ok,e=OrbMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then OrbMaker.woodStock=OrbMaker.woodStock-d.woodCost*qty end; if d.brassCost then OrbMaker.brassStock=OrbMaker.brassStock-d.brassCost*qty end; if d.silverCost then OrbMaker.silverStock=OrbMaker.silverStock-d.silverCost*qty end; if d.goldCost then OrbMaker.goldStock=OrbMaker.goldStock-d.goldCost*qty end; if d.jewelCost then OrbMaker.jewelStock=OrbMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then OrbMaker.pearlStock=OrbMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if OrbMaker.maker then t=math.max(1,t-math.floor(OrbMaker.maker.skill/12)) end; table.insert(OrbMaker.activeMaking,{id="orb_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function OrbMaker.completeMaking(m) local q=1.0+(OrbMaker.getQualityBonus()/100); if OrbMaker.maker then q=q+(OrbMaker.maker.skill/180) end; q=math.min(2.0,q); OrbMaker.productStock[m.productType]=(OrbMaker.productStock[m.productType] or 0)+m.quantity; OrbMaker.totalProducts=OrbMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if OrbMaker.maker then OrbMaker.maker.itemsMade=OrbMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then OrbMaker.maker.skill=math.min(100,OrbMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obel izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"orb.completed",{productName=m.productName,prestige=m.prestige}) end end
function OrbMaker.update(dt) if not _G.state then return end; OrbMaker.dayTimer=OrbMaker.dayTimer+dt; if OrbMaker.dayTimer>=30 then OrbMaker.dayTimer=0; for i=#OrbMaker.activeMaking,1,-1 do local m=OrbMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then OrbMaker.completeMaking(m); table.remove(OrbMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(OrbMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OrbMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OrbMaker.getStats() return {woodStock=OrbMaker.woodStock,brassStock=OrbMaker.brassStock,silverStock=OrbMaker.silverStock,goldStock=OrbMaker.goldStock,jewelStock=OrbMaker.jewelStock,pearlStock=OrbMaker.pearlStock,productStock=OrbMaker.productStock,numBuildings=#OrbMaker.buildings,hasMaker=OrbMaker.maker~=nil,makerName=OrbMaker.maker and OrbMaker.maker.name or "—",makerSkill=OrbMaker.maker and OrbMaker.maker.skill or 0,activeMaking=#OrbMaker.activeMaking,totalProducts=OrbMaker.totalProducts} end
return OrbMaker
